   const ahora=new Date(),fechaEntrega=ahora.toLocaleDateString("es-DO",{day:"2-digit",month:"2-digit",year:"numeric"}),codigo=`EPP-${ahora.getFullYear()}${String(ahora.getMonth()+1).padStart(2,"0")}${String(ahora.getDate()).padStart(2,"0")}`;
